var TT_W=10, TT_H=20;
var TT_SHAPES={
  I:[[0,0],[1,0],[2,0],[3,0]], O:[[0,0],[1,0],[0,1],[1,1]],
  T:[[0,0],[1,0],[2,0],[1,1]], S:[[1,0],[2,0],[0,1],[1,1]],
  Z:[[0,0],[1,0],[1,1],[2,1]], J:[[0,0],[0,1],[1,1],[2,1]], L:[[2,0],[0,1],[1,1],[2,1]]
};
var TT_TYPES=Object.keys(TT_SHAPES);
function ttRot(off){ return off.map(function(p){ return [-p[1], p[0]]; }); }
function ttClone(b){ return b.map(function(r){ return r.slice(); }); }
function ttEmpty(){ var g=[]; for(var y=0;y<TT_H;y++){ g.push(new Array(TT_W).fill(0)); } return g; }
function ttCells(type, rot){ var o=TT_SHAPES[type]; for(var i=0;i<(rot%4+4)%4;i++) o=ttRot(o); return o; }
function ttCollide(board, type, rot, x, y){
  var cells=ttCells(type,rot);
  for(var i=0;i<cells.length;i++){ var cx=x+cells[i][0], cy=y+cells[i][1];
    if(cx<0||cx>=TT_W||cy<0||cy>=TT_H) return true;
    if(cy>=0 && board[cy][cx]) return true; }
  return false;
}
function ttMerge(board, type, rot, x, y){
  var b=ttClone(board), cells=ttCells(type,rot);
  for(var i=0;i<cells.length;i++){ var cx=x+cells[i][0], cy=y+cells[i][1]; if(cy>=0) b[cy][cx]=type; }
  return b;
}
function ttClearLines(board){
  var cleared=0, nb=[];
  for(var y=0;y<TT_H;y++){ if(board[y].every(function(v){ return v; })) cleared++; else nb.push(board[y]); }
  while(nb.length<TT_H) nb.unshift(new Array(TT_W).fill(0));
  return {board:nb, cleared:cleared};
}
function ttNew(){
  return { board:ttEmpty(), type:TT_TYPES[Math.floor(Math.random()*7)], rot:0, x:3, y:0,
           next:TT_TYPES[Math.floor(Math.random()*7)], score:0, lines:0, over:false };
}
function ttStep(s){
  if(s.over) return s;
  if(ttCollide(s.board, s.type, s.rot, s.x, s.y+1)){ return ttLock(s); }
  s.y++; return s;
}
function ttLock(s){
  s.board=ttMerge(s.board, s.type, s.rot, s.x, s.y);
  var r=ttClearLines(s.board); s.board=r.board; s.lines+=r.cleared; s.score+=r.cleared*r.cleared*100;
  s.type=s.next; s.next=TT_TYPES[Math.floor(Math.random()*7)]; s.rot=0; s.x=3; s.y=0;
  if(ttCollide(s.board, s.type, s.rot, s.x, s.y)) s.over=true;
  return s;
}
function ttMove(s, dx){ if(!s.over && !ttCollide(s.board, s.type, s.rot, s.x+dx, s.y)) s.x+=dx; return s; }
function ttRotate(s){ var nr=(s.rot+1)%4; if(!ttCollide(s.board, s.type, nr, s.x, s.y)) s.rot=nr; return s; }
function ttHardDrop(s){ if(s.over) return s; while(!ttCollide(s.board, s.type, s.rot, s.x, s.y+1)) s.y++; return ttLock(s); }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { TT_W:TT_W, TT_H:TT_H, TT_SHAPES:TT_SHAPES, ttRot:ttRot, ttEmpty:ttEmpty,
    ttCells:ttCells, ttCollide:ttCollide, ttMerge:ttMerge, ttClearLines:ttClearLines, ttNew:ttNew,
    ttStep:ttStep, ttMove:ttMove, ttRotate:ttRotate, ttHardDrop:ttHardDrop };
}
if (typeof window !== 'undefined') {
  window.TetrisForgePure = { TT_W:TT_W, TT_H:TT_H, TT_SHAPES:TT_SHAPES, ttRot:ttRot, ttEmpty:ttEmpty,
    ttCells:ttCells, ttCollide:ttCollide, ttMerge:ttMerge, ttClearLines:ttClearLines, ttNew:ttNew,
    ttStep:ttStep, ttMove:ttMove, ttRotate:ttRotate, ttHardDrop:ttHardDrop };
}
